**What this code covers**

- Error budget for a single SLO over a fixed window.
- Total allowed bad-event-equivalent minutes in the window.
- Bad-event-equivalent minutes already consumed.
- How fast the budget is being consumed vs the steady-state rate.
- Error budget calculator: given SLO, time window, and observed
- Incidents, compute remaining budget, current burn rate, and
- Time elapsed in window (assume window is fully elapsed for
- The rolling-window snapshot view used in this demo).

```python
# Error budget calculator: given SLO, time window, and observed
# incidents, compute remaining budget, current burn rate, and
# recommended alerting action.

from dataclasses import dataclass
from datetime import timedelta

@dataclass
class ErrorBudget:
    """Error budget for a single SLO over a fixed window."""
    slo_percent: float          # e.g., 99.9
    window: timedelta           # e.g., 28 days
    good_events: int            # successful requests in window
    bad_events: int             # failed / slow requests in window

    @property
    def total_events(self) -> int:
        return self.good_events + self.bad_events

    @property
    def error_rate_percent(self) -> float:
        if self.total_events == 0:
            return 0.0
        return 100.0 * self.bad_events / self.total_events

    @property
    def allowed_error_rate_percent(self) -> float:
        return 100.0 - self.slo_percent

    @property
    def budget_minutes(self) -> float:
        """Total allowed bad-event-equivalent minutes in the window."""
        return self.allowed_error_rate_percent / 100.0 * \
               (self.window.total_seconds() / 60.0)

    @property
    def consumed_minutes(self) -> float:
        """Bad-event-equivalent minutes already consumed.

        Computed proportionally from event counts rather than wall-clock
        minutes, so it works for any request-rate shape.
        """
        if self.total_events == 0:
            return 0.0
        share = self.bad_events / self.total_events
        return share * (self.window.total_seconds() / 60.0)

    @property
    def remaining_minutes(self) -> float:
        return self.budget_minutes - self.consumed_minutes

    @property
    def remaining_percent(self) -> float:
        if self.budget_minutes == 0:
            return 0.0
        return 100.0 * self.remaining_minutes / self.budget_minutes

    @property
    def burn_rate(self) -> float:
        """How fast the budget is being consumed vs the steady-state rate.

        1.0 = on pace to exactly exhaust the budget over the window.
        14.0 = on pace to exhaust the budget in 1/14 of the window.
        """
        if self.consumed_minutes == 0:
            return 0.0
        # Time elapsed in window (assume window is fully elapsed for
        # the rolling-window snapshot view used in this demo).
        elapsed_fraction = 1.0  # rolling snapshot over the full window
        consumed_fraction = self.consumed_minutes / self.budget_minutes \
            if self.budget_minutes > 0 else float("inf")
        if elapsed_fraction == 0:
            return 0.0
        return consumed_fraction / elapsed_fraction

    def recommended_action(self) -> str:
        br = self.burn_rate
        if br >= 14:
            return f"Burn {br:.1f}x: PAGE on-call (acute incident)"
        if br >= 3:
            return f"Burn {br:.1f}x: open ticket (chronic problem)"
        if self.remaining_percent < 10:
            return f"Budget low ({self.remaining_percent:.1f}%): freeze releases"
        if br < 0.5:
            return f"Burn {br:.1f}x: ship features freely (budget healthy)"
        return f"Burn {br:.1f}x: nominal"

if __name__ == "__main__":
    import datetime as dt

    slo = 99.9
    window = dt.timedelta(days=28)
    total_per_day = 1_000_000  # 1M requests/day
    total_events = int(total_per_day * 28)

    # Each scenario: (name, error_rate_as_fraction_of_total)
    scenarios = [
        ("healthy",        0.0001),   # 99.99% actual (under SLO)
        ("on-pace",        0.001),    # 99.9% actual (exactly at SLO)
        ("slow-burn",      0.003),    # 99.7% actual (3x burn)
        ("acute-incident", 0.015),    # 98.5% actual (15x burn)
    ]
    for name, err_frac in scenarios:
        bad = int(err_frac * total_events)
        good = total_events - bad
        eb = ErrorBudget(
            slo_percent=slo, window=window,
            good_events=good, bad_events=bad,
        )
        print(f"\n=== {name} (actual error rate {err_frac*100:.2f}%) ===")
        print(f"  SLO:                {eb.slo_percent}%")
        print(f"  Error budget:       {eb.budget_minutes:.2f} min over {window}")
        print(f"  Consumed:           {eb.consumed_minutes:.2f} min")
        print(f"  Remaining:          {eb.remaining_minutes:.2f} min ({eb.remaining_percent:.1f}%)")
        print(f"  Burn rate:          {eb.burn_rate:.2f}x")
        print(f"  Recommended action: {eb.recommended_action()}")
